challenges.solution_code:
def parse_host_port(url: str) -> tuple[str, int]:
    cleaned = url.split('://', 1)[-1].split('/', 1)[0]
    if ':' in cleaned:
        h, p = cleaned.split(':', 1)
        return h, int(p)
    return cleaned, 443 if url.startswith('https://') else 80

def is_allowed_origin(origin: str, allowlist: list[str]) -> bool:
    normalized = origin.rstrip('/')
    return normalized in {item.rstrip('/') for item in allowlist}

def compute_backoff_ms(attempt: int, base_ms: int = 100, max_ms: int = 2000) -> int:
    if attempt <= 0:
        return base_ms
    return min(max_ms, base_ms * (2 ** attempt))

