function batchResize(widths, factor) {
  for (let i = 0; i < widths.length; i++) {
    widths[i] = widths[i] * factor;
  }
  return widths;
}

challenges.solution_code:
function batchResize(widths, factor) {
  return widths.map((w) => Math.round(w * factor));
}
